-- Scorpioplast product catalog: 17 verified tarp SKUs and 3 woven-bag products.
-- Public supplier website prices are REFERENCES ONLY, not supplier purchase costs or shop retail prices.
-- Shop prices intentionally remain NULL / "По запитване" until the merchant sets them.
ON CONFLICT (id) DO NOTHING;

CREATE TABLE IF NOT EXISTS public.vinyl_supplier_reference (
 product_id integer PRIMARY KEY REFERENCES public.vinyl_products(id) ON DELETE CASCADE,
 public_min_price numeric(12,2),
 public_max_price numeric(12,2),
 source text NOT NULL,
 recorded_at timestamptz NOT NULL DEFAULT now(),
 note text NOT NULL DEFAULT ''
);
ALTER TABLE public.vinyl_supplier_reference ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.vinyl_supplier_reference FROM PUBLIC, anon, authenticated;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (product_id) DO NOTHING;

ON CONFLICT (product_id,variant_key) DO NOTHING;
